#!/usr/bin/env bash
# Bundles seed-src/demo.ts into the self-contained src/db/seed-source.mjs that db:seed loads.
# Run after editing anything in seed-src/.
set -euo pipefail
npx --yes esbuild@0.21.5 seed-src/demo.ts \
  --bundle --format=esm --platform=node \
  --outfile=src/db/seed-source.mjs \
  --banner:js="/* GENERATED by scripts/gen-seed.sh from seed-src/ — do not edit by hand. */"
echo "regenerated src/db/seed-source.mjs"
